    cancelled = []
    monkeypatch.setattr("core.service.misp_auto_update.refresh_misp_auto_update_jobs", refreshed.extend)
    monkeypatch.setattr("core.service.misp_auto_update.cancel_misp_auto_update_jobs", cancelled.extend)

