                      attributes:
                      - id: '11'
                        title: Executive Summary
                        description: Summary field
                        index: 0
                        required: false
                        type: STRING
                        group_title: Workflow Group
                        render_data:
                          default_value: Default executive summary
                        value: Default executive summary
                      grouped_attributes:
                      - title: Workflow Group
                        attributes:
                        - id: '11'
                          title: Executive Summary
                          description: Summary field
                          index: 0
                          required: false
                          type: STRING
                          group_title: Workflow Group
                          render_data:
                            default_value: Default executive summary
                          value: Default executive summary
                      stories:
                      - id: story-100
                        title: VPN incident story
                    product:
                      id: product-456
                      title: CERT Daily Report - ACME VPN
                      description: Daily delivery for the ACME VPN advisory
                      created: '2026-03-30T16:00:00'
                      last_rendered: null
