def test_connector_task_execution_failure_is_persisted_safely(requests_mock, mock_job, monkeypatch, caplog):
    requests_mock.get(
        f"{Config.TARANIS_CORE_URL}/worker/connectors/connector-1",
        json={
            "id": "connector-1",
            "type": "misp_connector",
