    # 2. Strings containing \n, \t, and " should be preserved.
    input_special = 'Line1\nLine2\t"Quoted text"'
    cleaned_special = connector_tasks.drop_utf16_surrogates(input_special)
    print(f"cleaned_special: {cleaned_special}")
