        assert response.status_code == 207
        assert "errors" in response.get_json()

        # Tags list contains non-string elements
        response = client.put(f"{self.base_uri}/tags", json={news_item_id: [123, None]}, headers=api_header)
        assert response.status_code == 207
        assert "errors" in response.get_json()

